<template>
  <div>
    <NoDataWarningBanner
      :showBanner="showBanner"
      @dismiss="handleDismissBanner"
    />
    <div class="table-container">
      <DocBitsTable
        :rows="syncData"
        :columns="syncColumns"
        row-key="table_name"
        table-id="data_sync_table"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: false,
          resizable: false,
          pagination: false,
          columnReorder: false,
        }"
        no-data-label="no_record_found"
        flat-style
      >
        <template #body-cell-table_name="{ row }">
          {{ formateName(row.table_name) }}
        </template>
        <template #body-cell-created_on="{ row }">
          {{ formatDateAccordingToPreference(row.created_on) }}
        </template>
      </DocBitsTable>
    </div>
  </div>
</template>

<script lang="ts">
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import { importApiService } from 'src/services';
import NoDataWarningBanner from 'src/pages/Settings/Logs/NoDataWarningBanner.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  components: {
    NoDataWarningBanner,
    DocBitsTable,
  },
  mixins: [dateUtils],
  data() {
    return {
      syncData: [] as Array<{ table_name: string; created_on: string }>,
      showBanner: ref(false),
      syncColumns: [
        { name: 'table_name', label: 'Data Type', field: 'table_name', align: 'left' },
        { name: 'created_on', label: 'Last Synchronization Time', field: 'created_on', align: 'left' },
      ] as UnifiedTableColumn[],
    };
  },
  methods: {
    async fetchData() {
      try {
        let org_id = 'Placeholder for org_id';
        const response = await importApiService.fetchTableData(org_id);
        this.syncData = JSON.parse(response);

        this.syncData.sort(
          (a, b) =>
            new Date(b.created_on).getTime() - new Date(a.created_on).getTime(),
        );

        if (this.syncData.length === 0 || this.checkLatestUpdate()) {
          this.showBanner = true;
        } else {
          this.showBanner = false;
        }
      } catch (error) {
        logError('Error fetching data:', error);
      }
    },
    formateName(input: string): string {
      return input
        .split('_')
        .map(
          (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
        )
        .join(' ');
    },
    checkLatestUpdate() {
      const twoWeeksAgo = new Date();
      twoWeeksAgo.setDate(twoWeeksAgo.getDate() - 14);

      return this.syncData.every(
        (item) => new Date(item.created_on) < twoWeeksAgo,
      );
    },
    handleDismissBanner() {
      this.showBanner = false;
    },
  },
  mounted() {
    this.fetchData();
  },
});
</script>

<style lang="scss" scoped>
.table-container {
  max-height: 624px;
  overflow-y: auto;
  margin: 10px;
}
</style>
